def import_bookmarks(parser, cache, retry, logger, text):
    parsed = parser.parse(text)
    if cache.has(parsed):
        return cache.get(parsed)
    result = retry.run(lambda: parser.persist(parsed))
    logger.info(result)
    cache.put(parsed, result)
    return result

